"""FP8 quantization dispatch — direct cubin path with variant selection."""


import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled, warn_and_run_fallback
from kestrel_kernels.fp8_quant_cute.fallback import (
    fp8_block_quant_torch_into,
    fp8_quant_torch_into,
)

_family = CubinFamily("fp8_quant")
_KERNEL_KEY = "fp8_quant_cute"
_SUPPORTED_HIDDEN = {512, 1024, 2048, 5120, 6144, 17408}
_SUPPORTED_BLOCK_HIDDEN = {512, 1024, 2048, 4096}
_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _pick_warps_per_block(hidden: int, num_rows: int) -> int:
    # Benchmarked crossover: w=1 wins for h=2048 always (register pressure)
    # and for h=1024 up to ~512 rows; w=8 wins for h=1024 above that.
    if hidden >= 2048 or num_rows <= 512:
        return 1
    return 8


def _ensure_variant(
    variant_key: str,
    inp: torch.Tensor,
    *,
    hidden: int,
    warps_per_block: int,
    use_pdl: bool,
) -> bool:
    if _family.is_available(variant_key):
        return True
    device_index = int(inp.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_fp8_quant(
            hidden=hidden,
            warps_per_block=warps_per_block,
            use_pdl=use_pdl,
        ),
        block_x=warps_per_block * 32,
        device_index=device_index,
    )
    return True


def _ensure_block_variant(
    variant_key: str,
    inp: torch.Tensor,
    *,
    hidden: int | None,
    scale_major: str,
    persistent: bool,
    use_pdl: bool,
) -> bool:
    if _family.is_available(variant_key):
        return True
    device_index = int(inp.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if not _ENABLE_JIT:
        return False
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_cubin_bundles._compile_fp8_block_quant(
            hidden=hidden,
            scale_major=scale_major,
            persistent=persistent,
            use_pdl=use_pdl,
        ),
        block_x=256 if persistent else 32,
        device_index=device_index,
    )
    return True


def _use_persistent_block_quant(hidden: int, num_rows: int, scale_major: str) -> bool:
    if scale_major != "m":
        return False
    if hidden == 4096:
        return num_rows >= 64
    if hidden == 2048:
        return num_rows >= 128
    if hidden == 512:
        return num_rows >= 512
    return False


def _has_native_block_quant_variant(hidden: int) -> bool:
    return hidden in _SUPPORTED_BLOCK_HIDDEN or hidden % 128 == 0


def _validate_native_cuda_device(
    reference: torch.Tensor,
    tensors: tuple[tuple[str, torch.Tensor], ...],
) -> None:
    for name, tensor in tensors:
        if not tensor.is_cuda:
            raise ValueError(f"{name} must be a CUDA tensor")
        if tensor.device != reference.device:
            raise ValueError(
                f"{name} device {tensor.device} must match inp device {reference.device}"
            )


def fp8_quant_cute(
    out_bits: torch.Tensor,
    out_scale: torch.Tensor,
    inp: torch.Tensor,
    *,
    use_pdl: bool = False,
) -> None:
    num_rows, hidden = inp.shape
    if num_rows == 0:
        return

    warps_per_block = _pick_warps_per_block(hidden, num_rows)
    pdl_suffix = "_pdl" if use_pdl else ""
    variant_key = f"h{hidden}_w{warps_per_block}{pdl_suffix}"

    if hidden in _SUPPORTED_HIDDEN and inp.is_cuda:
        _validate_native_cuda_device(inp, (("out_bits", out_bits), ("out_scale", out_scale)))
        if _ensure_variant(
            variant_key,
            inp,
            hidden=hidden,
            warps_per_block=warps_per_block,
            use_pdl=use_pdl,
        ):
            grid_x = num_rows if warps_per_block == 1 else ceil_div(num_rows, warps_per_block)
            dispatch = _family.resolve_dispatch(inp, variant_key=variant_key, grid_x=grid_x)
            dispatch(out_bits, out_scale, inp)
            return

    warn_and_run_fallback(
        kernel_key=_KERNEL_KEY,
        message=f"kestrel-kernels: no fp8_quant cubin bundle for variant={variant_key!r}; using PyTorch fallback.",
        fallback=fp8_quant_torch_into,
        kwargs={"out_bits": out_bits, "out_scale": out_scale, "inp": inp},
    )


def fp8_block_quant_cute(
    out: torch.Tensor,
    out_scale: torch.Tensor,
    inp: torch.Tensor,
    *,
    use_pdl: bool = False,
) -> None:
    num_rows, hidden = inp.shape
    if num_rows == 0:
        return
    if inp.dtype != torch.bfloat16:
        raise ValueError(f"block FP8 quant expects bf16 input, got {inp.dtype}")
    if hidden % 128 != 0:
        raise ValueError(f"block FP8 quant expects K divisible by 128, got K={hidden}")
    expected_scale_shape = (num_rows, hidden // 128)
    if tuple(out.shape) != tuple(inp.shape):
        raise ValueError(f"out shape {tuple(out.shape)} must match input {tuple(inp.shape)}")
    if tuple(out_scale.shape) != expected_scale_shape:
        raise ValueError(
            f"out_scale shape {tuple(out_scale.shape)} must be {expected_scale_shape}"
        )
    if out.dtype not in (torch.float8_e4m3fn, torch.uint8):
        raise ValueError(f"block FP8 quant output must be fp8 e4m3 or uint8, got {out.dtype}")
    if out_scale.dtype != torch.float32:
        raise ValueError(f"block FP8 quant scale output must be float32, got {out_scale.dtype}")

    if out_scale.stride(-1) == 1:
        scale_major = "k"
        static_variant_key = f"block128_h{hidden}"
        dynamic_variant_key = "block128_dyn"
    elif out_scale.stride(-2) == 1:
        scale_major = "m"
        static_variant_key = f"block128_h{hidden}_mn"
        dynamic_variant_key = "block128_dyn_mn"
    else:
        raise ValueError(
            "block FP8 quant scale output must be contiguous K-major "
            f"or MN-major with stride(-2)=1, got stride={out_scale.stride()}"
        )

    persistent = _use_persistent_block_quant(hidden, num_rows, scale_major)
    use_pdl = bool(use_pdl and persistent)
    if persistent:
        variant_key = static_variant_key
        variant_key = f"{variant_key}_p"
        if use_pdl:
            variant_key = f"{variant_key}_pdl"
        compile_hidden: int | None = hidden
    elif hidden in _SUPPORTED_BLOCK_HIDDEN:
        variant_key = static_variant_key
        compile_hidden = hidden
    else:
        variant_key = dynamic_variant_key
        compile_hidden = None

    native_layout_ok = inp.stride(-1) == 1 and out.stride(-1) == 1
    if native_layout_ok and _has_native_block_quant_variant(hidden) and inp.is_cuda:
        _validate_native_cuda_device(inp, (("out", out), ("out_scale", out_scale)))
        if _ensure_block_variant(
            variant_key,
            inp,
            hidden=compile_hidden,
            scale_major=scale_major,
            persistent=persistent,
            use_pdl=use_pdl,
        ):
            grid_x = (
                min(
                    torch.cuda.get_device_properties(inp.device).multi_processor_count * 8,
                    ceil_div(num_rows * (hidden // 128), 8),
                )
                if persistent
                else num_rows
            )
            dispatch = _family.resolve_dispatch(
                inp,
                variant_key=variant_key,
                grid_x=grid_x,
                grid_y=1 if persistent else hidden // 128,
            )
            dispatch(out, out_scale, inp)
            return

    warn_and_run_fallback(
        kernel_key=_KERNEL_KEY,
        message=(
            "kestrel-kernels: block FP8 quant native path unavailable for "
            f"variant={variant_key!r}, native_layout_ok={native_layout_ok}; "
            "using PyTorch fallback."
        ),
        fallback=fp8_block_quant_torch_into,
        kwargs={"out": out, "out_scale": out_scale, "inp": inp},
    )


__all__ = ["fp8_block_quant_cute", "fp8_quant_cute"]
